PREFIX foaf: <http://xmlns.com/foaf/0.1/>
PREFIX VideoGameOntology: <http://example.org/VideoGameOntology#>

SELECT ?friend
WHERE {
  ?player VideoGameOntology:isFriendWithPlayer ?friend .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX VideoGameOntology: <http://example.org/VideoGameOntology/>

SELECT ?event
WHERE {
  ?event rdf:type VideoGameOntology:InstantaneousEvent ;
         VideoGameOntology:isEventInSession ?session .
}

PREFIX VideoGameOntology: <http://example.org/VideoGameOntology#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?game
WHERE {
  ?character VideoGameOntology:isCharacterInGame ?game .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX VideoGameOntology: <http://example.org/VideoGameOntology/>

SELECT (COUNT(DISTINCT ?eventType) AS ?numberOfEventTypes) ?eventType
WHERE {
  ?eventType rdfs:subClassOf* VideoGameOntology:GameEvent .
  OPTIONAL {
    ?eventType rdfs:subClassOf VideoGameOntology:InstantaneousEvent .
  }
}
GROUP BY ?eventType
ORDER BY DESC(?numberOfEventTypes)

