PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX VideoGameOntology: <http://example.org/VideoGameOntology/>

SELECT ?loseEvent ?description
WHERE {
  ?loseEvent rdf:type VideoGameOntology:LoseEvent .
  OPTIONAL {
    ?loseEvent rdfs:comment ?description
  }
  FILTER NOT EXISTS {
    ?loseEvent rdf:type ?otherType .
    FILTER(?otherType != VideoGameOntology:LoseEvent && ?otherType != owl:Class)
  }
}

