# Write your query here.
PREFIX VideoGameOntology: <http://example.org/VideoGameOntology#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?eventName ?eventTime
WHERE {
  ?session rdf:type VideoGameOntology:Session ;
           VideoGameOntology:startTime ?startTime ;
           VideoGameOntology:endTime ?endTime .
  ?player rdf:type VideoGameOntology:Player ;
          VideoGameOntology:username "given_player_username" .
  ?event rdf:type VideoGameOntology:InstantaneousEvent ;
         VideoGameOntology:eventName ?eventName ;
         VideoGameOntology:eventTime ?eventTime .
  FILTER(?eventTime >= ?startTime && ?eventTime <= ?endTime)
}

PREFIX VideoGameOntology: <http://example.org/VideoGameOntology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?player (MAX(?duration) AS ?longestSessionDuration)
WHERE {
  ?session a VideoGameOntology:Session ;
           VideoGameOntology:startTime ?startTime ;
           VideoGameOntology:endTime ?endTime ;
           VideoGameOntology:username ?player .
  BIND(xsd:dateTime(?endTime) - xsd:dateTime(?startTime) AS ?duration)
}
GROUP BY ?player

